mapper.select:
SELECT t1.`id`, t1.`name`, t1.`level_code`, t1.`emergency_event_type_code`, t2.`name` as `emergency_event_type_name`, t1.`expiration_status`, t1.`expiration_date`, t1.`remark`, t1.`document_file_id`, t1.`process_file_id`, t1.`tenant`, t1.`deleted`, t1.`create_by`, t1.`creator_id`, t1.`creator_type`, t1.`create_time`, t1.`update_by`, t1.`updater_id`, t1.`updater_type`, t1.`update_time` FROM `emergency_file` t1 LEFT JOIN `emergency_event_type` t2 on t1.`emergency_event_type_code` = t2.`code`
and t1.`update_time` > #{period.begin}
and t1.`update_time` <= #{period.end}

SELECT t1.`name` AS `emergency_event_type_name` FROM `emergency_event_type` t1
t1.`code` NOT IN
#{code}

SELECT t1.`id`, t1.`name`, t1.`emergency_file_type_id`, t3.`name` as `emergency_file_type_name`, t1.`level_code`, t1.`expiration_date`, t1.`expiration_status`, t1.`emergency_event_type_code`, t2.`name` AS `emergency_event_type_name`, t1.`remark`, t1.`document_file_id`, t1.`process_file_id`, t1.`tenant`, t1.`deleted`, t1.`create_by`, t1.`creator_id`, t1.`creator_type`, t1.`create_time`, t1.`update_by`, t1.`updater_id`, t1.`updater_type`, t1.`update_time` FROM `emergency_file` t1 LEFT JOIN `emergency_event_type` t2 ON t1.`emergency_event_type_code` = t2.`code` LEFT JOIN `emergency_file_type` t3 on t1.`emergency_file_type_id` = t3.`id`
and (t1.`name` like concat('%',#{param.keyword},'%') or t2.`name` like concat('%',#{param.keyword},'%'))
and t1.`emergency_event_type_code` = #{param.emergencyEventTypeCode}
and t1.`level_code` = #{param.levelCode}
and t1.`expiration_status` = #{param.expirationStatus}
order by t1.`create_time` desc
